package dev.ide.index.impl

import dev.ide.index.Externalizer
import dev.ide.index.IndexExtension
import dev.ide.index.IndexId
import dev.ide.index.IndexInput
import dev.ide.index.IndexOrigin
import dev.ide.index.InputFilter
import dev.ide.index.KeyDescriptor
import dev.ide.index.MatchingMode
import dev.ide.index.StringExternalizer
import dev.ide.index.StringKeyDescriptor

/**
 * One real segment, written by the JVM writer and checked in, so the reader can be run where the writer
 * cannot: [SegmentReadTest] queries these exact bytes on the iOS simulator.
 *
 * `SegmentFixtureTest` rebuilds it on every JVM run and fails if it has drifted, so the fixture cannot
 * quietly stop being what the writer produces.
 */
internal object SegmentFixture {

    val ENTRIES: List<IndexEntry> = buildList {
        // Enough terms to need more than one block at the reader's small cache size, sharing prefixes so the
        // sparse index and the prefix walk are both exercised, and repeated values so the string pool is too.
        for (i in 0 until 120) {
            add(IndexEntry("Item%03d".let { _ -> "Item" + i.toString().padStart(3, '0') }, "value$i", IndexOrigin.LIBRARY))
        }
        add(IndexEntry("Widget", "shared", IndexOrigin.LIBRARY))
        add(IndexEntry("Wombat", "shared", IndexOrigin.LIBRARY))
        add(IndexEntry("Widget", "second", IndexOrigin.LIBRARY))
    }

    fun extension(): IndexExtension<String, String> = object : IndexExtension<String, String> {
        override val id = IndexId("test.fixture")
        override val version = 1
        override val keyDescriptor: KeyDescriptor<String> = StringKeyDescriptor
        override val valueExternalizer: Externalizer<String> = StringExternalizer
        override val matching = MatchingMode.PREFIX_AND_FUZZY
        override val inputFilter = InputFilter { true }
        override fun index(input: IndexInput): Map<String, Collection<String>> = emptyMap()
    }

    /** Replaced from `SegmentFixtureTest`'s failure message whenever the format changes. */
    const val BASE64: String = ""
}
